"""K05 — M5: HMM-guided 6DoF on RobotCar Seasons v2 (train queries, test split of PROTOCOL v1).
Candidates (k=3, same budget) from single-image retrieval vs HMM posterior (computed offline on CPU, embedded below).
Local features: SuperPoint (max 2048 kp) + LightGlue; 2D-3D from the dataset SfM model all.nvm (SuperPoint keypoints within
3 px of an NVM observation inherit its 3D point); PnP-RANSAC (OpenCV). Reports (0.25m,2°)/(0.5m,5°)/(5m,10°)."""
import os, sys, json, zlib, base64, time, glob, shutil, re
import numpy as np, torch, cv2
CAND = json.loads(zlib.decompress(base64.b64decode("")))
t00 = time.time(); DEV = "cuda" if torch.cuda.is_available() else "cpu"
print("torch", torch.__version__, DEV, torch.cuda.get_device_name(0) if DEV == "cuda" else "", "queries", len(CAND), flush=True)
def walk_find(root, name, depth=6):
    for d, subs, fs in os.walk(root):
        if d.count(os.sep) - root.count(os.sep) >= depth: subs[:] = []
        if name in fs: return os.path.join(d, name)
    return None
nvm = walk_find("/kaggle/input", "all.nvm"); trtxt = walk_find("/kaggle/input", "robotcar_v2_train.txt")
RC = nvm.split("/3D-models")[0]; print("nvm", nvm, "| train", trtxt, flush=True)
intr = walk_find("/kaggle/input", "rear_intrinsics.txt") or None
# --- LightGlue sources + offline weights
lg = None
for d, subs, fs in os.walk("/kaggle/input"):
    if os.path.basename(d) == "lightglue" and "lightglue.py" in fs: lg = os.path.dirname(d); break
print("lightglue src:", lg, flush=True); sys.path.insert(0, lg)
ck = os.path.dirname(walk_find("/kaggle/input", "superpoint_v1.pth"))
hub = os.path.expanduser("~/.cache/torch/hub/checkpoints"); os.makedirs(hub, exist_ok=True)
for f in ("superpoint_v1.pth", "superpoint_lightglue_v0-1_arxiv.pth"): shutil.copy(os.path.join(ck, f), hub)
from lightglue import LightGlue, SuperPoint
from lightglue.utils import load_image, rbd
ext = SuperPoint(max_num_keypoints=2048).eval().to(DEV); mat = LightGlue(features="superpoint").eval().to(DEV)
# --- image index
idx = {}
for d, _, fs in os.walk(os.path.join(RC, "images")):
    cam = os.path.basename(d)
    for f in fs:
        if f.lower().endswith((".jpg", ".png")): idx[(cam, os.path.splitext(f)[0])] = os.path.join(d, f)
print("images indexed", len(idx), flush=True)
need = {str(t) for v in CAND.values() for l in v.values() for t in l}
# --- NVM: reference cameras + 3D points observed in needed references
def q2R(q):
    w, x, y, z = q
    return np.array([[1-2*(y*y+z*z), 2*(x*y-z*w), 2*(x*z+y*w)], [2*(x*y+z*w), 1-2*(x*x+z*z), 2*(y*z-x*w)], [2*(x*z-y*w), 2*(y*z+x*w), 1-2*(x*x+y*y)]])
cams = {}; t0 = time.time()
with open(nvm) as fh:
    fh.readline(); line = fh.readline()
    while not line.strip(): line = fh.readline()
    n = int(line.split()[0]); camidx = {}
    for i in range(n):
        t = fh.readline().split(); parts = t[0].replace("\\", "/").split("/")
        ts = os.path.splitext(parts[-1])[0]
        if parts[-3] == "overcast-reference" and parts[-2] == "rear" and ts in need:
            camidx[i] = ts; cams[ts] = {"f": float(t[1]), "R": q2R(list(map(float, t[2:6]))), "C": np.array(list(map(float, t[6:9])))}
    line = fh.readline()
    while not line.strip(): line = fh.readline()
    npts = int(line.split()[0]); obs = {ts: [] for ts in cams}
    for k in range(npts):
        t = fh.readline().split()
        nm = int(t[6])
        for m in range(nm):
            ci = int(t[7 + 4 * m])
            if ci in camidx:
                obs[camidx[ci]].append((float(t[9 + 4 * m]), float(t[10 + 4 * m]), float(t[0]), float(t[1]), float(t[2])))
        if k % 500000 == 0: print(f"  points {k}/{npts} ({time.time()-t0:.0f}s)", flush=True)
obs = {k: np.array(v, np.float64).reshape(-1, 5) for k, v in obs.items()}
print("ref cams", len(cams), "/", len(need), "| mean obs/ref", np.mean([len(v) for v in obs.values()]), f"{time.time()-t0:.0f}s", flush=True)
# --- GT query poses
GT = {}
for ln in open(trtxt):
    t = ln.split()
    if len(t) >= 17: M = np.array(list(map(float, t[1:17]))).reshape(4, 4); GT[t[0]] = (M[:3, 3].copy(), M[:3, :3].copy())
@torch.no_grad()
def feats(path):
    im = load_image(path).to(DEV); return ext.extract(im), tuple(im.shape[-2:])
FC = {}
def get(path):
    if path not in FC: FC[path] = feats(path)
    return FC[path]
def ref3d(ts):
    f, (H, W) = get(idx[("rear", ts)]); kp = f["keypoints"][0].cpu().numpy(); o = obs.get(ts)
    X = np.full((len(kp), 3), np.nan)
    if o is None or len(o) == 0: return X
    from scipy.spatial import cKDTree
    uv = o[:, :2] + np.array([W / 2.0, H / 2.0]); d, j = cKDTree(uv).query(kp, distance_upper_bound=3.0)
    ok = np.isfinite(d); X[ok] = o[j[ok], 2:5]; return X
R3 = {}; PAIR = {}
@torch.no_grad()
def match(qp, ts):
    key = (qp, ts)
    if key not in PAIR:
        fq, _ = get(qp); fr, _ = get(idx[("rear", ts)])
        out = rbd(mat({"image0": fq, "image1": fr})); m = out["matches"].cpu().numpy()
        PAIR[key] = m
    return PAIR[key]
def rot_err(Ra, Rb): return float(np.degrees(np.arccos(np.clip((np.trace(Ra.T @ Rb) - 1) / 2, -1, 1))))
METHODS = sorted({k for v in CAND.values() for k in v}); RES = {m: [] for m in METHODS}; t0 = time.time()
for qi, (qn, cd) in enumerate(CAND.items()):
    cond, cam, ts = qn.split("/")[0], qn.split("/")[-2], os.path.splitext(qn.split("/")[-1])[0]
    qp = idx.get((cam, ts)); gt = GT.get(qn)
    if qp is None or gt is None: continue
    fq, (H, W) = get(qp); kq = fq["keypoints"][0].cpu().numpy()
    for m in METHODS:
        P2, P3 = [], []
        for rts in cd[m]:
            rts = str(rts)
            if ("rear", rts) not in idx: continue
            if rts not in R3: R3[rts] = ref3d(rts)
            mm = match(qp, rts); X = R3[rts][mm[:, 1]]; ok = np.isfinite(X[:, 0])
            P2.append(kq[mm[ok, 0]]); P3.append(X[ok])
        P2 = np.concatenate(P2) if P2 else np.zeros((0, 2)); P3 = np.concatenate(P3) if P3 else np.zeros((0, 3))
        f0 = cams[str(cd[m][0])]["f"] if str(cd[m][0]) in cams else 400.0
        K = np.array([[f0, 0, W / 2.0], [0, f0, H / 2.0], [0, 0, 1]])
        rec = {"q": qn, "cond": cond, "n2d3d": int(len(P2)), "ok": False}
        retr = cams.get(str(cd[m][0]))
        if retr is not None:
            rec["retr_dt"] = float(np.linalg.norm(retr["C"] - gt[0])); rec["retr_dr"] = rot_err(gt[1], retr["R"].T)
        if len(P2) >= 6:
            ok, rv, tv, inl = cv2.solvePnPRansac(P3.astype(np.float64), P2.astype(np.float64), K, None, iterationsCount=5000,
                                                  reprojectionError=8.0, confidence=0.9999, flags=cv2.SOLVEPNP_EPNP)
            if ok and inl is not None and len(inl) >= 12:
                Rw = cv2.Rodrigues(rv)[0]; C = -Rw.T @ tv.ravel()
                rec.update(ok=True, inliers=int(len(inl)), dt=float(np.linalg.norm(C - gt[0])), dr=rot_err(gt[1], Rw.T))
        RES[m].append(rec)
    if qi % 100 == 0: print(f"  q {qi}/{len(CAND)} pairs {len(PAIR)} ({time.time()-t0:.0f}s)", flush=True)
THR = [(0.25, 2.0), (0.5, 5.0), (5.0, 10.0)]
os.makedirs("/kaggle/working/out", exist_ok=True); json.dump(RES, open("/kaggle/working/out/k05_results.json", "w"))
for m, L in RES.items():
    n = len(L); dt = np.array([r.get("dt", 1e9) for r in L]); dr = np.array([r.get("dr", 1e9) for r in L])
    rt = np.array([r.get("retr_dt", 1e9) for r in L]); rr = np.array([r.get("retr_dr", 1e9) for r in L])
    acc = [float(np.mean((dt <= a) & (dr <= b))) for a, b in THR]; racc = [float(np.mean((rt <= a) & (rr <= b))) for a, b in THR]
    night = np.array([r["cond"].startswith("night") for r in L])
    accn = [float(np.mean(((dt <= a) & (dr <= b))[night])) for a, b in THR]
    print(f"{m:16s} n={n} PnP {'/'.join(f'{x:.3f}' for x in acc)} | night {'/'.join(f'{x:.3f}' for x in accn)} | retrieval-pose {'/'.join(f'{x:.3f}' for x in racc)} | median dt {np.median(dt):.2f} m", flush=True)
print("K05_DONE", f"{time.time()-t00:.0f}s", flush=True)
